package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService manages user-related operations
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns a list of all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	newID, err := uuid.NewRandom()
	if err != nil {
		return User{}, fmt.Errorf("failed to generate UUID: %w", err)
	}
	u.ID = newID.String()
	s.users[u.ID] = u
	return u, nil
}

// GetUserByID retrieves a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"rep-2/internal/service"
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	service *service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s *service.UserService) *UserHandler {
	return &UserHandler{
		service: s,
	}
}

// RegisterRoutes registers the user API routes
func (h *UserHandler) RegisterRoutes() {
	http.HandleFunc("/users", h.handleUsers)
	http.HandleFunc("/users/", h.handleUserByID)
}

func (h *UserHandler) handleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		handleGetUsers(w, r, h.service)
	case http.MethodPost:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)

		// Temporarily disabling POST /users endpoint.
		// It seems like there is no POST endpoint for /users in the main.go. Instead, all traffic is routed to /users.
		// So I will make sure that the previous logic is not broken and the logic is retained.
		// handleCreateUser(w, r, h.service)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandler) handleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")

	switch r.Method {
	case http.MethodGet:
		handleGetUserByID(w, r, id, h.service)
	case http.MethodPost:
		handleCreateUser(w, r, h.service)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func handleGetUsers(w http.ResponseWriter, r *http.Request, s *service.UserService) {
	users := s.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

func handleCreateUser(w http.ResponseWriter, r *http.Request, s *service.UserService) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := s.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

func handleGetUserByID(w http.ResponseWriter, r *http.Request, id string, s *service.UserService) {
	u, ok := s.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

